    map['body'] = Variable<String>(body);
    if (!nullToAbsent || route != null) {
      map['route'] = Variable<String>(route);
    }
    map['received_at'] = Variable<DateTime>(receivedAt);
    map['is_read'] = Variable<bool>(isRead);
    return map;
  }

